#pragma once
// Model plugins: shared libraries generated by fdgen with model-specific element types
// (expression forces). Loaded once per process, never unloaded.

#include <string>

#include "fd_registry.h"

namespace fd {

// Load the plugin (if not loaded yet) and register its element types. Throws if the library
// cannot be loaded or was generated for another registry layout (FD_REGISTRY_ABI).
void load_plugin(const std::string& path);
// Element type of a loaded plugin, nullptr if none has it.
const fd_element_type* find_plugin_element_type(const std::string& name);

}  // namespace fd
